    "La ceremonia de zarpe, desarrollada en la Base Naval del Callao, estuvo liderada por la mandataria Keiko Fujimori, el ministro de Defensa, Rafael Belaúnde, y el comandante general de la Marina, Javier Bravo de Rueda."
